// Read from JSON file
function readDB(): Application[] {
  try {
    if (!fs.existsSync(DB_FILE)) {
      fs.writeFileSync(DB_FILE, JSON.stringify(initialSeed, null, 2), "utf8");
      return initialSeed;
    }
    const data = fs.readFileSync(DB_FILE, "utf8");
    return JSON.parse(data);
  } catch (err) {
    console.error("Error reading database file", err);
    return [];
  }
}

// Write to JSON file
function writeDB(data: Application[]) {
  try {
    fs.writeFileSync(DB_FILE, JSON.stringify(data, null, 2), "utf8");
  } catch (err) {
    console.error("Error writing database file", err);
  }
}

// Helper to get client IP behind Nginx reverse proxy
function getClientIp(req: express.Request): string {
  const forwarded = req.headers["x-forwarded-for"];
  if (forwarded) {
    const ips = (forwarded as string).split(",");
    return ips[0].trim();
  }
  return req.ip || req.socket.remoteAddress || "127.0.0.1";
}

// Simple HTML/JS stripping function to prevent XSS
function cleanHTML(text: string): string {
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#x27;")
    .replace(/\//g, "&#x2F;");
}

async function start() {
  const app = express();

  // Allow larger payloads to accommodate base64 profile pictures (max 10MB)
  app.use(express.json({ limit: "10mb" }));
  app.use(express.urlencoded({ limit: "10mb", extended: true }));

  // Crucial for capturing real user IP through proxy headers
  app.set("trust proxy", true);

  // --- HELPER VALIDATION & SANITIZATION ---
  function validateNickname(name: string): string | null {
    if (!name) {
      return "El nombre dentro del grupo es obligatorio.";
    }
    const trimmed = name.trim();
    if (trimmed.length < 3 || trimmed.length > 30) {
      return "El apodo debe tener entre 3 y 30 caracteres.";
    }

    // No links/URLs
    const linkRegex = /(https?:\/\/|www\.[a-zA-Z0-9-]+\.[a-zA-Z]{2,5}|[a-zA-Z0-9-]+\.(com|net|org|edu|gov|io|info|me|cl|mx|co|es))\b/i;
    if (linkRegex.test(trimmed)) {
      return "No se permiten enlaces o páginas web en el apodo.";
    }

    // No phone numbers (7 or more consecutive digits, allowing optional spaces/hyphens)
    const phoneRegex = /(\+?\d[\s-]?){7,}/;
    if (phoneRegex.test(trimmed)) {
      return "No se permiten números de teléfono en el apodo.";
    }

    // No email addresses
    const emailRegex = /[\w.-]+@[\w.-]+\.[a-zA-Z0-9]{2,}/;
    if (emailRegex.test(trimmed)) {
      return "No se permiten correos electrónicos en el apodo.";
    }

    // Insults / Offensive words
    const spanishProfanity = [
      "pendejo", "mierda", "puto", "puta", "cabron", "cabrón", "culero", "maricon", "maricón",
      "imbecil", "imbécil", "perra", "malparido", "hdp", "hpta", "hp", "asshole", "bitch", "fuck", "shit", "gonorrea", "idiota"
    ];
    const normalizedName = trimmed.toLowerCase();
    const hasProfanity = spanishProfanity.some(word => normalizedName.includes(word));
    if (hasProfanity) {
      return "El apodo contiene palabras inadecuadas u ofensivas.";
    }

    // No names made entirely of symbols
    const hasAlphanumeric = /[a-zA-Z0-9áéíóúÁÉÍÓÚñÑ]/.test(trimmed);
    if (!hasAlphanumeric) {
      return "El apodo no puede estar formado únicamente por símbolos.";
    }

    return null;
  }

  // --- API ROUTES ---

  // 1. Get public listing of applicants (Safety filtered: no IPs or private hashes exposed!)
  app.get("/api/applications", (req, res) => {
    const db = readDB();
    // Return only list of registered users sorted from newest to oldest
    const publicList = db.map(({ id, nickname, date, avatarUrl, bio }) => ({
      id,
      nickname,
      date,
      avatarUrl: avatarUrl || DEFAULT_AVATAR,
      bio: bio || ""
    }));
    
    // Sort from newest to oldest
    publicList.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    res.json(publicList);
  });

  // 1b. Get candidate profile details by secure token
  app.get("/api/applications/me", (req, res) => {
    const token = (req.header("x-auth-token") || req.query.token) as string;
    if (!token) {
      return res.status(401).json({ error: "Falta el token de autorización." });
    }

    const db = readDB();
    const hashed = hashToken(token);
    const applicant = db.find(app => app.tokenHash === hashed);

    if (!applicant) {
      return res.status(404).json({ error: "No se encontró ningún perfil asociado a este token." });
    }

    res.json({
      success: true,
      application: {
        id: applicant.id,
        nickname: applicant.nickname,
        date: applicant.date,
        status: applicant.status,
        avatarUrl: applicant.avatarUrl || DEFAULT_AVATAR,
        bio: applicant.bio || ""
      }
    });
  });

  // 2. Submit new application
  app.post("/api/applications", (req, res) => {
    const rawIp = getClientIp(req);
    const { nickname, avatarUrl, bio } = req.body;

    // A. Validate nickname
    const validationError = validateNickname(nickname);
    if (validationError) {
      return res.status(400).json({ error: validationError });
    }

    // B. Validate bio if provided
    if (bio && typeof bio === "string" && bio.length > 200) {
      return res.status(400).json({ error: "La descripción/biografía no puede superar los 200 caracteres." });
    }

    const name = nickname.trim();

    // B. Check for duplicate IP (Exclude any elements that had their IP cleared null)
    const db = readDB();
    if (rawIp) {
      const duplicate = db.find(app => app.ip === rawIp);
      if (duplicate) {
        return res.status(400).json({ error: "⚠️ Ya existe una postulación registrada desde esta conexión. Si perdiste el acceso para editar tu perfil, comunícate con un administrador." });
      }
    }

    // C. Clean HTML/JS code snippets
    const cleanName = cleanHTML(name);
    const cleanBio = bio ? cleanHTML(bio.trim()) : "";

    // D. Generate high entropy token
    const secureToken = "tok_" + crypto.randomBytes(36).toString("hex");
    const securedHash = hashToken(secureToken);

    // Save
    const newApplication: Application = {
      id: `app-${Date.now()}-${Math.random().toString(36).substring(2, 6)}`,
      nickname: cleanName,
      date: new Date().toISOString(),
      status: "pending",
      avatarUrl: avatarUrl ? avatarUrl.trim() : DEFAULT_AVATAR,
      ip: rawIp || null,
      tokenHash: securedHash,
      bio: cleanBio
    };

    db.push(newApplication);
    writeDB(db);

    res.json({ 
      success: true, 
      token: secureToken,
      application: { 
        id: newApplication.id, 
        nickname: newApplication.nickname, 
        date: newApplication.date,
        status: newApplication.status,
        avatarUrl: newApplication.avatarUrl,
        bio: newApplication.bio
      } 
    });
  });

  // 2b. Edit personal candidate details (Secured via private token only)
  app.put("/api/applications/me/update", (req, res) => {
    const token = req.header("x-auth-token") as string;
    const { nickname, avatarUrl, bio } = req.body;

    if (!token) {
      return res.status(401).json({ error: "Falta el token para autorizar la edición." });
    }

    const validationError = validateNickname(nickname);
    if (validationError) {
      return res.status(400).json({ error: validationError });
    }

    // Validate bio if provided
    if (bio && typeof bio === "string" && bio.length > 200) {
      return res.status(400).json({ error: "La descripción/biografía no puede superar los 200 caracteres." });
    }

    const name = nickname.trim();
    const cleanName = cleanHTML(name);
    const cleanBio = bio ? cleanHTML(bio.trim()) : "";

    const db = readDB();
    const hashed = hashToken(token);
    const index = db.findIndex(app => app.tokenHash === hashed);

    if (index === -1) {
      return res.status(403).json({ error: "Token inválido o expirado. No tienes autorización para realizar cambios." });
    }

    // Apply updates (Only nickname, photo, and biography adaptations allowed, never state or log ip!)
    db[index].nickname = cleanName;
    db[index].avatarUrl = avatarUrl ? avatarUrl.trim() : DEFAULT_AVATAR;
    db[index].bio = cleanBio;

    writeDB(db);

    res.json({
      success: true,
      message: "Tu perfil ha sido actualizado con éxito.",
      application: {
        id: db[index].id,
        nickname: db[index].nickname,
        date: db[index].date,
        status: db[index].status,
        avatarUrl: db[index].avatarUrl,
        bio: db[index].bio || ""
      }
    });
  });

  // 3. Admin Authentication Login checking
  app.post("/api/admin/auth", (req, res) => {
    const { passcode } = req.body;
    // Set passcode exactly to #Smith099 with no defaults or bypasses
    if (passcode === "#Smith099") {
      res.json({ success: true, token: "admin-secret-access-token" });
    } else {
      res.status(401).json({ error: "Contraseña incorrecta. Intente de nuevo." });
    }
  });

  // 4. Admin detailed fetch (Returns secure attributes including state/notes/ratings)
  app.get("/api/admin/applications", (req, res) => {
    const db = readDB();
    // Sort from newest to oldest
    const sorted = [...db].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    res.json(sorted);
  });

  // 5. Update Status & Notes & Rating
  app.put("/api/admin/applications/:id", (req, res) => {
    const { id } = req.params;
    const { status, notes, rating } = req.body;

    const db = readDB();
    const index = db.findIndex(app => app.id === id);
    if (index === -1) {
      return res.status(404).json({ error: "Postulación no encontrada." });
    }

    if (status) db[index].status = status;
    if (notes !== undefined) db[index].notes = notes;
    if (rating !== undefined) db[index].rating = rating;

    writeDB(db);
    res.json({ success: true, application: db[index] });
  });

  // 5b. Admin trigger: Generate brand new edit token (Invalides old hash completely)
  app.post("/api/admin/applications/:id/regen-token", (req, res) => {
    const { id } = req.params;
    const db = readDB();
    const index = db.findIndex(app => app.id === id);
    if (index === -1) {
      return res.status(404).json({ error: "Postulación no encontrada." });
    }

    // Generate brand new high entropy secure token
    const newRawToken = "tok_" + crypto.randomBytes(36).toString("hex");
    db[index].tokenHash = hashToken(newRawToken);

    writeDB(db);
    res.json({ 
      success: true, 
      rawToken: newRawToken,
      message: "Se generó un nuevo enlace de edición. El anterior ha quedado invalidado."
    });
  });

  // 6. Allow IP again (Zero or null out the IP)
  app.post("/api/admin/applications/:id/unlock-ip", (req, res) => {
    const { id } = req.params;
    const db = readDB();
    const index = db.findIndex(app => app.id === id);
    if (index === -1) {
      return res.status(404).json({ error: "Postulación no encontrada." });
    }

    db[index].ip = null; // Unlocked!
    writeDB(db);
    res.json({ success: true, message: "IP liberada con éxito.", application: db[index] });
  });

  // 7. Delete an application completely
  app.delete("/api/admin/applications/:id", (req, res) => {
    const { id } = req.params;
    let db = readDB();
    const initialLength = db.length;
    db = db.filter(app => app.id !== id);
    
    if (db.length === initialLength) {
      return res.status(404).json({ error: "Postulación no encontrada." });
    }

    writeDB(db);
    res.json({ success: true, message: "Postulación eliminada." });
  });

  // 8. Seeding custom mock test candidates with automatic mock tokens
  app.post("/api/admin/seed", (req, res) => {
    const db = readDB();
    const names = ["MasterGamerr_V", "PentaKill_Lover", "Zero_Cool", "Sky_Blade", "NexusFrenzy"];
    const avatars = [
      "https://images.unsplash.com/photo-1542751371-adc38448a05e?auto=format&fit=crop&q=80&w=150",
      "https://images.unsplash.com/photo-1552820728-8b83bb6b773f?auto=format&fit=crop&q=80&w=150",
      DEFAULT_AVATAR
    ];

    const randomName = `${names[Math.floor(Math.random() * names.length)]}_${Math.floor(10 + Math.random() * 90)}`;
    const randomAvatar = avatars[Math.floor(Math.random() * avatars.length)];
    const mockSeedToken = "tok_seeded_" + Math.random().toString(36).substring(2);

    const seedApp: Application = {
      id: `app-${Date.now()}`,
      nickname: randomName,
      date: new Date().toISOString(),
      status: "pending",
      avatarUrl: randomAvatar,
      ip: `seeded-${Math.floor(Math.random() * 1000)}`,
      tokenHash: hashToken(mockSeedToken)
    };

    db.push(seedApp);
    writeDB(db);
    res.json({ success: true, application: seedApp });
  });

  // 9. Reset database to initial mock seeds
  app.post("/api/admin/reset", (req, res) => {
    writeDB(initialSeed);
    res.json({ success: true, applications: initialSeed });
  });

  // --- DEV & PRODUCTION COMPILATION INGRESS HANDLERS ---

  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), "dist");
    app.use(express.static(distPath));
    app.get("*", (req, res) => {
      res.sendFile(path.join(distPath, "index.html"));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server loaded running on: http://0.0.0.0:${PORT}`);
  });
}

start();
